    // Paso 1: Cuenta elementos por bucket
    for (int valor : arr)
        conteo[(valor / exp) % 10]++;
    // Paso 2: Calcula la suma acumulada
    for (int j = 1; j < 10; j++)
        conteo[j] += conteo[j - 1];
    // Paso 3: Inserta los elementos en la nueva posición
    for (int j = n - 1; j >= 0; j--) {
        int d = (arr[j] / exp) % 10;
        salida[conteo[d] - 1] = arr[j];
